474	#[cfg(test)]
475	mod resume_tests {
476	    use super::*;
477	    use crate::{CancellationToken, HookRegistry, MemorySession, Session, TracerHandle};
478	    use std::sync::{Arc, Mutex};
479	
480	    // Runner that records how many input messages its run/run_streamed saw.
481	    #[derive(Default)]
482	    struct CapturingRunner {
483	        last_len: Arc<Mutex<Option<usize>>>,
484	    }
485	
486	    #[async_trait]
487	    impl Runner<()> for CapturingRunner {
488	        async fn run(
489	            &self,
490	            _agent: &(dyn Agent<()> + '_),
491	            _ctx: RunContext<()>,
492	            input: AgentInput,
493	            _config: RunConfig,
494	        ) -> Result<RunResult, RunError> {
495	            *self.last_len.lock().unwrap() = Some(input.messages.len());
496	            Ok(RunResult::default())
497	        }
498	        async fn run_streamed(
499	            &self,
500	            _agent: &(dyn Agent<()> + '_),
501	            _ctx: RunContext<()>,
502	            input: AgentInput,
503	            _config: RunConfig,
504	        ) -> Result<RunResultStreaming, RunError> {
505	            *self.last_len.lock().unwrap() = Some(input.messages.len());
506	            let s: futures_core::stream::BoxStream<'static, AgentEvent> =
507	                Box::pin(futures_util::stream::empty());
508	            Ok(RunResultStreaming::new(s))
509	        }
510	    }
511	
512	    struct DummyAgent;
513	    #[async_trait]
514	    impl Agent<()> for DummyAgent {
515	        fn name(&self) -> &str {
516	            "dummy"
517	        }
518	        fn description(&self) -> &str {
519	            "dummy"
520	        }
521	        async fn run(
522	            &self,
523	            _ctx: RunContext<()>,
524	            _input: AgentInput,
525	        ) -> Result<futures_core::stream::BoxStream<'static, AgentEvent>, AgentError> {
526	            Ok(Box::pin(futures_util::stream::empty()))
527	        }
528	    }
529	
530	    fn ctx() -> RunContext<()> {
531	        RunContext::new(
532	            Arc::new(()),
533	            Arc::new(MemorySession::new()) as Arc<dyn Session>,
534	            HookRegistry::new(),
535	            TracerHandle::default(),
536	            CancellationToken::new(),
537	        )
538	    }
539	
540	    #[tokio::test]
541	    async fn resume_delegates_to_run_with_empty_input() {
542	        let r = CapturingRunner::default();
543	        r.resume(&DummyAgent, ctx(), RunConfig::default())
544	            .await
545	            .unwrap();
546	        assert_eq!(*r.last_len.lock().unwrap(), Some(0));
547	    }
548	
549	    #[tokio::test]
550	    async fn resume_streamed_delegates_with_empty_input() {
551	        let r = CapturingRunner::default();
552	        let _ = r
553	            .resume_streamed(&DummyAgent, ctx(), RunConfig::default())
554	            .await
555	            .unwrap();
556	        assert_eq!(*r.last_len.lock().unwrap(), Some(0));
557	    }
558	}
