569	    #[test]
570	    fn run_config_defaults_and_builders() {
571	        let c = RunConfig::default();
572	        assert_eq!(c.max_turns, 16);
573	        assert!(c.timeout.is_none());
574	        assert!(c.parallel_tool_call_limit.is_none());
575	        assert_eq!(c.max_agent_depth, 8);
576	
577	        let c = RunConfig::new()
578	            .with_timeout(std::time::Duration::from_secs(5))
579	            .with_parallel_tool_call_limit(std::num::NonZeroUsize::new(3).unwrap());
580	        assert_eq!(c.timeout, Some(std::time::Duration::from_secs(5)));
581	        assert_eq!(c.parallel_tool_call_limit, std::num::NonZeroUsize::new(3));
582	
583	        let c = RunConfig::new().with_max_agent_depth(3);
584	        assert_eq!(c.max_agent_depth, 3);
585	    }
