1	//! Explicit state machine for the agent loop.
2	//!
3	//! Per ADR *"Explicit `LoopState` enum, not a callback maze"*, the
4	//! state machine is data: a pure [`transition`] function takes the
5	//! current state plus the most recent input and returns the next
6	//! state, the events to emit, and the side effect to perform. Durable
7	//! runners (Temporal, AgentCore in later tickets) reuse the same
8	//! function with their own driver.
9	
10	use crate::{
11	    AgentError, AgentEvent, ContentPart, FinishReason, Item, ModelRequest, ModelSettings,
12	    ResponseFormat, TokenUsage, ToolDef,
13	};
14	
15	/// The explicit, observable state of the agent loop.
16	///
17	/// One variant per high-level phase. Does **not** derive `Clone`:
18	/// `Failed(AgentError)` wraps `anyhow::Error` (not `Clone`). The
19	/// transition function takes input and returns outcome by value; tests
20	/// use `assert_matches!` on `next_state` instead of equality.
21	#[derive(Debug)]
22	#[non_exhaustive]
23	pub enum LoopState {
24	    /// About to call the model for turn `turn`.
25	    CallingModel {
26	        /// Zero-indexed turn counter.
27	        turn: u32,
28	        /// Cumulative token usage of all model turns completed before turn
29	        /// `turn` (SMA-402); `default()` at turn 0. Folded forward on every
30	        /// transition; the terminal `Done` / `RunCompleted` carry the grand total.
31	        usage: TokenUsage,
32	    },
33	    /// The model produced tool calls; about to execute them. `turn` is
34	    /// the turn that produced the calls — the next [`LoopState::CallingModel`]
35	    /// state will be `turn + 1`.
36	    ExecutingTools {
37	        /// The tool calls to execute concurrently.
38	        calls: Vec<ToolCallRequest>,
39	        /// The turn that produced these calls.
40	        turn: u32,
41	        /// Cumulative token usage of all model turns completed so far —
42	        /// including the turn that produced these calls (SMA-402). Carried
43	        /// forward unchanged across tool execution (tools add no tokens).
44	        usage: TokenUsage,
45	    },
46	    /// Handing off to another agent; carries the threaded transcript and the
47	    /// cumulative usage of all turns completed before the handoff (SMA-324).
48	    ApplyingHandoff {
49	        /// Name of the target agent.
50	        target: String,
51	        /// Conversation transcript to hand off.
52	        transcript: Vec<Item>,
53	        /// Cumulative usage of turns completed before the handoff.
54	        usage: TokenUsage,
55	    },
56	    /// Compacting session history. **Not driveable in SMA-314.**
57	    Compacting,
58	    /// Awaiting approval for a sensitive tool call.
59	    /// **Not driveable in SMA-314.**
60	    NeedsApproval {
61	        /// The tool calls awaiting approval.
62	        pending: Vec<ToolCallRequest>,
63	    },
64	    /// Constrained finalizing turn: the model is asked to emit the
65	    /// structured output for the configured `output_type`.
66	    Finalizing {
67	        /// The turn index that produced this finalizing request.
68	        turn: u32,
69	        /// Cumulative token usage of all model turns completed so far,
70	        /// including the turn that triggered finalizing (SMA-402).
71	        usage: TokenUsage,
72	    },
73	    /// The one allowed repair turn after a failed finalizing validation.
74	    RepairingOutput {
75	        /// The turn index of the finalizing turn being repaired.
76	        turn: u32,
77	        /// Cumulative token usage of all model turns completed so far,
78	        /// including the failed finalizing turn (SMA-402).
79	        usage: TokenUsage,
80	    },
81	    /// Terminal: run completed successfully.
82	    Done(FinalOutput),
83	    /// Terminal: run failed.
84	    Failed(AgentError),
85	}
