119	impl FinalOutput {
120	    /// Concatenate all `ContentPart::Text` parts. This is the
121	    /// canonical rendering that feeds `RunResult.final_output` when
122	    /// `T = String`.
123	    pub fn as_text(&self) -> String {
124	        self.content
125	            .iter()
126	            .filter_map(|p| match p {
127	                ContentPart::Text { text } => Some(text.as_str()),
128	                _ => None,
129	            })
130	            .collect::<Vec<_>>()
131	            .join("")
132	    }
133	}
