135	/// Data fed *into* the next [`transition`] call.
136	#[derive(Debug, Clone)]
137	#[non_exhaustive]
138	pub enum TransitionInput {
139	    /// Seeds the loop with the initial conversation.
140	    Start {
141	        /// The user's input messages.
142	        messages: Vec<Item>,
143	    },
144	    /// One model turn aggregated.
145	    ModelResponse {
146	        /// Items produced this turn (assistant message + tool calls).
147	        items: Vec<Item>,
148	        /// Token usage for this turn.
149	        usage: TokenUsage,
150	        /// Why the model stopped emitting tokens.
151	        finish_reason: FinishReason,
152	    },
153	    /// All tool calls for one turn have completed.
154	    ToolResults {
155	        /// Per-call outcomes.
