160	/// Side effect the async driver must run before the next transition.
161	#[derive(Debug, Clone)]
162	#[non_exhaustive]
163	pub enum NextAction {
164	    /// Call the model with this request; produce a `ModelResponse`.
165	    CallModel {
166	        /// The request to send.
167	        request: ModelRequest,
168	    },
169	    /// Execute these tool calls concurrently; produce a `ToolResults`.
170	    ExecuteTools {
171	        /// The calls to fan out.
172	        calls: Vec<ToolCallRequest>,
173	    },
174	    /// The current state is terminal; stop driving.
175	    Terminate,
176	    /// Delegate to a handoff target. The driver reads the target, transcript,
177	    /// and pre-handoff usage from the [`LoopState::ApplyingHandoff`] state.
178	    Handoff,
179	}
