181	/// What [`transition`] needs to know about the agent and config for
182	/// one step. Doesn't carry user `Ctx` — that's the driver's concern.
183	pub struct TransitionCtx<'a> {
184	    /// Tool definitions available this run.
185	    pub tools: &'a [ToolDef],
186	    /// Provider-tuning knobs.
187	    pub model_settings: &'a ModelSettings,
188	    /// Maximum number of turns before the loop fails.
189	    pub max_turns: u32,
190	    /// The driver's accumulated conversation so far. The driver
191	    /// appends incoming items before calling [`transition`] and passes
192	    /// the slice in — [`transition`] reads but never mutates.
193	    pub conversation: &'a [Item],
194	    /// Structured-output type, when the agent configured one. Drives the
195	    /// constrained finalizing turn and output validation.
196	    pub output: Option<&'a crate::OutputType>,
197	    /// Synthetic transfer-tool descriptors, one per handoff candidate. Empty
198	    /// when the agent has no handoffs.
199	    pub handoffs: &'a [crate::HandoffDef],
200	}
201	
202	/// One transition step's result. Not `Clone` (carries `LoopState`).
203	#[derive(Debug)]
204	pub struct TransitionOutcome {
205	    /// The state after this step.
206	    pub next_state: LoopState,
207	    /// Events to yield through the driver's event stream.
208	    pub events: Vec<AgentEvent>,
209	    /// Side effect the driver must run before the next step.
210	    pub next_action: NextAction,
211	    /// Items the driver must append to its owned conversation before the
212	    /// next step (e.g. a synthesized repair message). Empty in most arms.
213	    pub conversation_appends: Vec<Item>,
214	}
215	
216	/// Pure state-machine step. **No async, no tokio, no IO.**
217	///
218	/// Given the current state and the most recent input, produce the
219	/// next state, the events to emit, and the side effect to perform.
220	/// Resumable by construction: a durable runner can persist
221	/// [`LoopState`] plus the accumulated conversation and rehydrate the
222	/// loop at any transition boundary.
223	pub fn transition(
224	    state: &LoopState,
225	    input: TransitionInput,
226	    ctx: &TransitionCtx<'_>,
227	) -> TransitionOutcome {
228	    match (state, input) {
229	        // Max turns reached at the CallingModel boundary → fail fast.
230	        (LoopState::CallingModel { turn, .. }, _) if *turn >= ctx.max_turns => TransitionOutcome {
231	            next_state: LoopState::Failed(AgentError::MaxTurnsExceeded(ctx.max_turns)),
232	            events: vec![AgentEvent::RunFailed {
233	                error: format!("max turns ({}) exceeded", ctx.max_turns),
234	            }],
235	            next_action: NextAction::Terminate,
236	            conversation_appends: Vec::new(),
237	        },
238	        // Start seeds the loop: emit TurnStarted, request CallModel.
239	        (LoopState::CallingModel { turn, usage: prior }, TransitionInput::Start { .. })
240	            if *turn < ctx.max_turns =>
241	        {
242	            match ctx.output {
243	                Some(out) if ctx.tools.is_empty() => {
244	                    let request = ModelRequest {
245	                        messages: ctx.conversation.to_vec(),
246	                        tools: Vec::new(),
247	                        model_settings: constrained_settings(ctx.model_settings, out),
248	                    };
249	                    TransitionOutcome {
250	                        next_state: LoopState::Finalizing {
251	                            turn: *turn,
252	                            usage: *prior,
253	                        },
254	                        events: vec![AgentEvent::TurnStarted { turn: *turn }],
255	                        next_action: NextAction::CallModel { request },
256	                        conversation_appends: Vec::new(),
257	                    }
258	                }
259	                _ => {
260	                    let request = ModelRequest {
261	                        messages: ctx.conversation.to_vec(),
262	                        tools: turn_tools(ctx),
263	                        model_settings: ctx.model_settings.clone(),
264	                    };
265	                    TransitionOutcome {
266	                        next_state: LoopState::CallingModel {
267	                            turn: *turn,
268	                            usage: *prior,
269	                        },
270	                        events: vec![AgentEvent::TurnStarted { turn: *turn }],
271	                        next_action: NextAction::CallModel { request },
272	                        conversation_appends: Vec::new(),
273	                    }
274	                }
275	            }
276	        }
277	        // Model produced tool calls → fan out to ExecutingTools.
278	        (
279	            LoopState::CallingModel { turn, usage: prior },
280	            TransitionInput::ModelResponse { items, usage, .. },
281	        ) if items.iter().any(|i| matches!(i, Item::ToolCall { .. })) => {
282	            // Handoff takes precedence over regular tool calls (first wins).
283	            if let Some(target) = items.iter().find_map(|i| match i {
284	                Item::ToolCall { name, .. } => ctx
285	                    .handoffs
286	                    .iter()
287	                    .find(|h| &h.tool_name == name)
288	                    .map(|h| h.target.clone()),
289	                _ => None,
290	            }) {
291	                let total = accumulate(*prior, usage);
292	                let mut events: Vec<AgentEvent> = Vec::new();
293	                for item in &items {
294	                    match item {
295	                        Item::AssistantMessage { .. } => {
296	                            events.push(AgentEvent::MessageOutput { item: item.clone() });
297	                        }
298	                        Item::ToolCall { name, .. }
299	                            if ctx.handoffs.iter().any(|h| &h.tool_name == name) =>
300	                        {
301	                            events.push(AgentEvent::ToolCallItem { item: item.clone() });
302	                        }
303	                        _ => {}
304	                    }
305	                }
306	                return TransitionOutcome {
307	                    next_state: LoopState::ApplyingHandoff {
308	                        target,
309	                        transcript: thread_handoff_transcript(ctx.conversation),
310	                        usage: total,
311	                    },
312	                    events,
313	                    next_action: NextAction::Handoff,
314	                    conversation_appends: Vec::new(),
315	                };
316	            }
317	            // (existing ExecutingTools logic continues unchanged below)
318	            let mut events: Vec<AgentEvent> = Vec::new();
319	            let mut calls: Vec<ToolCallRequest> = Vec::new();
320	            for item in &items {
321	                match item {
322	                    Item::AssistantMessage { .. } => {
323	                        events.push(AgentEvent::MessageOutput { item: item.clone() });
324	                    }
325	                    Item::ToolCall {
326	                        call_id,
327	                        name,
328	                        args,
329	                    } => {
330	                        events.push(AgentEvent::ToolCallItem { item: item.clone() });
331	                        calls.push(ToolCallRequest {
332	                            call_id: call_id.clone(),
333	                            name: name.clone(),
334	                            args: args.clone(),
335	                        });
336	                    }
337	                    _ => {}
338	                }
339	            }
340	            TransitionOutcome {
341	                next_state: LoopState::ExecutingTools {
342	                    calls: calls.clone(),
343	                    turn: *turn,
344	                    usage: accumulate(*prior, usage),
345	                },
346	                events,
347	                next_action: NextAction::ExecuteTools { calls },
348	                conversation_appends: Vec::new(),
349	            }
350	        }
351	        // Model produced a response with no tool calls → either issue a
352	        // constrained finalizing turn (output set) or terminate (no output).
353	        (
354	            LoopState::CallingModel { turn, usage: prior },
355	            TransitionInput::ModelResponse { items, usage, .. },
356	        ) if !items.iter().any(|i| matches!(i, Item::ToolCall { .. })) => {
357	            let total = accumulate(*prior, usage);
358	            let mut events: Vec<AgentEvent> = items
359	                .iter()
360	                .filter(|i| matches!(i, Item::AssistantMessage { .. }))
361	                .cloned()
362	                .map(|item| AgentEvent::MessageOutput { item })
363	                .collect();
364	
365	            match ctx.output {
366	                Some(out) => {
367	                    // Phase 2: issue one constrained finalizing turn (real tools
368	                    // withdrawn; the prior unconstrained answer stays in context).
369	                    // The finalizing call is a distinct model invocation, so it
370	                    // gets its own turn number (the unconstrained turn already
371	                    // emitted `TurnStarted { turn }`).
372	                    let finalizing_turn = *turn + 1;
373	                    let request = ModelRequest {
374	                        messages: ctx.conversation.to_vec(),
375	                        tools: Vec::new(),
376	                        model_settings: constrained_settings(ctx.model_settings, out),
377	                    };
